.wemd-image-compare[data-variant="bytedance-compare-side"] {
  margin: 16px 0;
}
.wemd-image-compare[data-variant="bytedance-compare-side"] .wemd-component-body {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.wemd-image-compare[data-variant="bytedance-compare-side"] .wemd-component-body .wemd-child-1 {
  flex: 1;
  min-width: 45%;
  background: var(--wemd-bg-soft);
  border-radius: var(--wemd-border-radius);
  padding: 8px;
  margin: 0;
  text-align: center;
}
.wemd-image-compare[data-variant="bytedance-compare-side"] .wemd-component-body .wemd-child-2 {
  flex: 1;
  min-width: 45%;
  background: var(--wemd-primary-light);
  border-radius: var(--wemd-border-radius);
  padding: 8px;
  margin: 0;
  text-align: center;
}
.wemd-image-compare[data-variant="bytedance-compare-side"] .wemd-component-body .wemd-child-3 {
  color: var(--wemd-text-soft);
